                    { id: 2418, type: "physical", n: "Стена/потолок", w: 3, t: window.formatNorms("Предельное отклонение по горизонтали не более 3 мм на 1 м (СП 71.13330.2017, табл. 7.4, улучшенная штукатурка)") },
                    { id: 2419, type: "physical", n: "Оконные/дверные откосы, пилястры, столбы", w: 3, t: window.formatNorms("Отклонение от вертикали и горизонтали на площади 4м2 не более 4 мм на 1 м, но не более 10 мм на весь элемент (СП 71.13330.2017, табл. 7.4, улучшенная штукатурка, откосы)") },
                    { id: 2420, type: "physical", n: "Ширина откоса", w: 2, t: window.formatNorms("Отклонение от проектной ширины не более 3 мм (СП 71.13330.2017, табл. 7.4, улучшенная штукатурка, ширина откоса)") }
