                    { id: 2614, type: "physical", n: "Использование ПМД при замесе", w: 2, t: window.formatNorms("СП 70.13330.2012. При температуре менее +5°С. СП 70.13330.2012 (порог применения противоморозных добавок / зимнего бетонирования).") },
                    { id: 2615, type: "physical", n: "Приготовление раствора", w: 3, t: window.formatNorms(`Согласно проекта, требование на сжатие. Использование фибры.`) },
                    { id: 2616, type: "physical", n: "Применение доп. Армирования в местах прохождения трубопроводов", w: 2, t: window.formatNorms(`Согласно проекта`) }
