                group: "5. Допуски, отклонения, высыхание", items: [
                    { id: 2617, type: "physical", n: "Отклонение от горизонтали и местные неровности", w: 3, t: window.formatNorms("ППР. Уклон до 0.2 % но не более 20 мм на помещение.\nПри устройстве гидроизоляционного покрытия – 5 мм\nСтяжки под ламинат, паркет, линолеум – 2 мм\nВыравнивающих стяжек под покрытия других типов – 4 мм") },
                    { id: 2618, type: "physical", n: "Устройство температурно-усадочных швов", w: 3, t: window.formatNorms("Проект, ППР, СП 29.13330.2011, п. 8.14. Шаг ≤6 м. На границах разных помещений.") },
                    { id: 2619, type: "physical", n: "Качество заглаживания поверхности", w: 3, t: window.formatNorms("СП 71.13330.2017, табл. 8.2. Без видимых дефектов, шероховатостей поверхности, качественно заглажена") },
                    { id: 2620, type: "physical", n: "Прочность на сжатие готовой стяжки спустя 28 суток", w: 3, t: window.formatNorms("СП 29.13330.2011, п. 8.5, Тех. карта ≥15 Мпа") },
                    { id: 2621, type: "physical", n: "Соблюдение ТВР в период высыхания", w: 3, t: window.formatNorms("\"СП 71.13330.2017\" п. 8.1, 8.1.12. Не допускаются: сквозняки, влажные условия не менее 7 суток после укладки(укрытие пленкой), поддержание ТВР не менее +5°С") },
                    { id: 2622, type: "physical", n: "Отсутствие видимых дефектов", w: 2, t: window.formatNorms("Тех. карта, ППР. Не допускаются: трещины Ширина ≤0,5 мм, длина ≤100 мм., прогиб углов.") },
                ]
